eight:700;padding:4px 12px;border-radius:20px;letter-spacing:0.5px;">#${sProtocolo}</span></td></tr></table><table role="presentation" border="0" cellpadding="0" cellspacing="0" width="100%" style="background:#ffffff;border-radius:8px;border:1px solid #e5e7eb;margin-bottom:20px;"><tr><td colspan="2" style="padding:14px 18px;border-bottom:1px solid #f3f4f6;"><p style="margin:0 0 2px;font-size:11px;color:#9ca3af;text-transform:uppercase;letter-spacing:1px;">Empresa</p><p style="margin:0;font-size:14px;font-weight:600;color:#111827;">${sEmpresa}</p></td></tr><tr><td width="50%" style="padding:14px 18px;border-bottom:1px solid #f3f4f6;border-right:1px solid #f3f4f6;"><p style="margin:0 0 2px;font-size:11px;color:#9ca3af;text-transform:uppercase;letter-spacing:1px;">Pavimento</p><p style="margin:0;font-size:14px;font-weight:600;color:#111827;">${sPavimento}</p></td><td width="50%" style="padding:14px 18px;border-bottom:1px solid #f3f4f6;"><p style="margin:0 0 2px;font-size:11px;color:#9ca3af;text-transform:uppercase;letter-spacing:1px;">Sala</p><p style="margin:0;font-size:14px;font-weight:600;color:#111827;">${sSala}</p></td></tr><tr><td colspan="2" style="padding:14px 18px;"><p style="margin:0 0 2px;font-size:11px;color:#9ca3af;text-transform:uppercase;letter-spacing:1px;">Servi&ccedil;o</p><p style="margin:0;font-size:14px;font-weight:600;color:#111827;">${sServico}</p></td></tr></table>${highlightBox}<p style="margin:0;font-size:11px;color:#9ca3af;line-height:1.6;border-top:1px solid #f3f4f6;padding-top:16px;">Este &eacute; um e-mail autom&aacute;tico. Por favor, n&atilde;o responda diretamente a esta mensagem. Em caso de d&uacute;vidas, entre em contato com a administra&ccedil;&atilde;o do condom&iacute;nio.</p></td></tr><tr><td style="padding:16px 28px;background:#f3f4f6;border-top:1px solid #e5e7eb;"><table role="presentation" border="0" cellpadding="0" cellspacing="0" width="100%"><tr><td style="font-size:11px;color:#9ca3af;">&copy; ${new Date().getFullYear()} Condom&iacute;nio Salvador Trade Center</td><td align="right" style="font-size:11px;color:#9ca3af;">Todos os direitos reservados.</td></tr></table></td></tr></table></td></tr></table></body></html>`

    const response = await fetch('https://api.resend.com/emails', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${RESEND_API_KEY}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        from: `Comitê - Salvador Trade Center <${ADMIN_EMAIL}>`,
        to: email,
        subject: `Solicitação #${sProtocolo} - ${isAprovado ? 'APROVADA' : 'REPROVADA'}`,
        html: emailHtml,
      })
    })

    const result = await response.json()

    if (!response.ok) {
      console.error('Erro Resend:', result)
      return new Response(
        JSON.stringify({ error: result.message || 'Erro ao enviar e-mail' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      )
    }

    return new Response(
      JSON.stringify({ success: true, message: 'E-mail de resposta enviado com sucesso' }),
      { status: 200, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    )

  } catch (error) {
    console.error('Erro:', error)
    return new Response(
      JSON.stringify({ error: error.message }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    )
  }
