import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

const supabaseUrl = Deno.env.get('SUPABASE_URL')!
const supabaseServiceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!

export type AuthError = Response

/** Extrai e valida o JWT. Retorna o user ou uma Response de erro. */
export async function requireAuth(req: Request): Promise<{ id: string; email?: string } | Response> {
  const authHeader = req.headers.get('Authorization')
  if (!authHeader) {
    return new Response(JSON.stringify({ error: 'Não autorizado' }), {
      status: 401,
      headers: { 'Content-Type': 'application/json' },
    })
  }

  const token = authHeader.replace('Bearer ', '')
  const supabase = createClient(supabaseUrl, supabaseServiceKey)
  const { data: { user }, error } = await supabase.auth.getUser(token)

  if (error || !user) {
    return new Response(JSON.stringify({ error: 'Token inválido ou expirado' }), {
      status: 401,
      headers: { 'Content-Type': 'application/json' },
    })
  }

  return user
}

/** Valida JWT e verifica se o usuário tem role 'master' na tabela perfis. */
export async function requireMaster(req: Request): Promise<{ id: string; email?: string } | Response> {
  const userOrError = await requireAuth(req)
  if (userOrError instanceof Response) return userOrError

  const supabase = createClient(supabaseUrl, supabaseServiceKey)
  const { data: perfil } = await supabase
    .from('perfis')
    .select('role')
    .eq('id', userOrError.id)
    .single()

  if (perfil?.role !== 'master') {
    return new Response(JSON.stringify({ error: 'Acesso restrito a usuários master' }), {
      status: 403,
      headers: { 'Content-Type': 'application/json' },
    })
  }

  return userOrError
}

