import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
}

const RATE_LIMIT = 5        // máximo de submissões
const WINDOW_MINUTES = 60   // por janela de 60 minutos

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { status: 200, headers: corsHeaders })
  }

  try {
    const supabaseUrl = Deno.env.get('SUPABASE_URL')!
    const supabaseServiceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!
    const supabase = createClient(supabaseUrl, supabaseServiceKey)

    // Rate limiting por IP
    const ip = req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ?? 'unknown'
    const windowStart = new Date()
    windowStart.setMinutes(windowStart.getMinutes() - WINDOW_MINUTES)

    const { count } = await supabase
      .from('rate_limit')
      .select('*', { count: 'exact', head: true })
      .eq('ip', ip)
      .gte('window_start', windowStart.toISOString())

    if ((count ?? 0) >= RATE_LIMIT) {
      return new Response(
        JSON.stringify({ error: 'Muitas solicitações. Tente novamente em 1 hora.' }),
        { status: 429, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      )
    }

    await supabase.from('rate_limit').insert({ ip })

    // Limpa registros antigos
    await supabase.from('rate_limit').delete().lt('window_start', windowStart.toISOString())

    const { records } = await req.json()

